from collections.abc import Sequence

def repeat_tuples(seq, n):
    if not isinstance(seq, Sequence):
        raise TypeError("Input must be a sequence")
    if n < 0:
        raise ValueError("n must be non-negative")
    repeated = [seq] * n
    if isinstance(seq, tuple):
        return tuple(repeated)
    elif isinstance(seq, list):
        return repeated
    elif isinstance(seq, str):
        return ''.join(repeated)
    elif isinstance(seq, range):
        # range is immutable and cannot be directly repeated, convert to list of ranges
        return tuple(repeated)
    else:
        # For other sequence types, try to reconstruct using the type constructor
        try:
            return type(seq)(repeated)
        except Exception:
            # fallback to list
            return repeated
```

