def next_smallest_palindrome(num: int) -> int:
    def is_all_nines(n: int) -> bool:
        return all(ch == '9' for ch in str(n))

    s = str(num)
    length = len(s)

    # If all digits are 9, next palindrome is 10...01
    if is_all_nines(num):
        return num + 2  # e.g. 9 -> 11, 99 -> 101, 999 -> 1001

    def make_palindrome(left: str, odd_length: bool) -> str:
        # Construct palindrome by mirroring left to right
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    # Increment the palindrome base
    def increment_middle(left: str, odd_length: bool) -> str:
        if odd_length:
            # middle is last char of left
            left_num = int(left)
            left_num += 1
            return str(left_num)
        else:
            left_num = int(left)
            left_num += 1
            return str(left_num)

    while True:
        s = str(num + 1)
        length = len(s)
        odd_length = (length % 2 != 0)
        mid = length // 2

        if odd_length:
            left = s[:mid+1]
        else:
            left = s[:mid]

        palindrome = make_palindrome(left, odd_length)
        if int(palindrome) > num:
            return int(palindrome)
        else:
            # Need to increment the left part and build again
            left = increment_middle(left, odd_length)
            # Handle length increase after increment (e.g. 999 -> 1000)
            if len(left) > (mid + 1 if odd_length else mid):
                # Length increased, so palindrome length increases by 1
                length += 1
                odd_length = (length % 2 != 0)
                mid = length // 2
                if odd_length:
                    left = '1' + ('0' * (mid))
                    palindrome = make_palindrome(left, odd_length)
                else:
                    left = '1' + ('0' * (mid - 1))
                    palindrome = make_palindrome(left, odd_length)
                return int(palindrome)
            palindrome = make_palindrome(left, odd_length)
            if int(palindrome) > num:
                return int(palindrome)
            num = int(palindrome) - 1  # set num so next iteration increments properly
