from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    groups = []
    current_group = []
    balance = 0

    for char in paren_string:
        if char == '(':
            current_group.append(char)
            balance += 1
        elif char == ')':
            current_group.append(char)
            balance -= 1
            if balance == 0:
                groups.append(''.join(current_group))
                current_group = []
        elif char == ' ':
            # Space may separate groups, but consecutive balanced parentheses without spaces are one group
            if balance == 0 and current_group:
                groups.append(''.join(current_group))
                current_group = []
        else:
            # Ignore other characters (not specified in the problem)
            pass

    # Append any remaining group if balanced
    if current_group and balance == 0:
        groups.append(''.join(current_group))

    results = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for c in group:
            if c == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif c == ')':
                current_depth -= 1
        results.append(max_depth)
    return results
