def anti_shuffle(s):
    def sort_word(word):
        return ''.join(sorted(word))

    # Split input into words and spaces, keeping spaces as separate tokens
    tokens = re.findall(r'\S+|\s+', s)

    # Sort letters in words, leave spaces as is
    result = []
    for token in tokens:
        if token.isspace():
            result.append(token)
        else:
            result.append(sort_word(token))
    return ''.join(result)
